package com.sabyeguyz.clinic.masterdata; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@org.springframework.context.annotation.Profile("!database-v2")
@RestController @RequestMapping("/api/master-data") public class MasterDataController {
 private final MasterDataRepository repo; public MasterDataController(MasterDataRepository r){repo=r;} public record Request(@NotBlank String category,@NotBlank String code,@NotBlank String name,Boolean active){} public record Response(Long id,String category,String code,String name,boolean active){}
 @GetMapping List<Response> list(){return repo.findAllByOrderByCategoryAscNameAsc().stream().map(this::out).toList();} @GetMapping("/{id}") Response get(@PathVariable Long id){return out(find(id));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) Response create(@Valid @RequestBody Request r){String c=norm(r.category()),code=norm(r.code());if(repo.findByCategoryAndCode(c,code).isPresent())throw new IllegalArgumentException("รหัสข้อมูลพื้นฐานซ้ำในหมวดเดียวกัน");MasterData x=new MasterData(c,code,r.name().trim());applyActive(x,r.active());return out(repo.save(x));}
 @PutMapping("/{id}") Response update(@PathVariable Long id,@Valid @RequestBody Request r){MasterData x=find(id);String c=norm(r.category()),code=norm(r.code());if(repo.findByCategoryAndCode(c,code).filter(v->!v.getId().equals(id)).isPresent())throw new IllegalArgumentException("รหัสข้อมูลพื้นฐานซ้ำในหมวดเดียวกัน");x.update(c,code,r.name().trim());applyActive(x,r.active());return out(repo.save(x));}
 @PatchMapping("/{id}/activate") Response activate(@PathVariable Long id){MasterData x=find(id);x.activate();return out(repo.save(x));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){MasterData x=find(id);x.deactivate();repo.save(x);}
 private MasterData find(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("ไม่พบข้อมูลพื้นฐาน"));} private String norm(String s){return s.trim().toUpperCase();} private static void applyActive(MasterData x,Boolean active){if(active!=null){if(active)x.activate();else x.deactivate();}} private Response out(MasterData x){return new Response(x.getId(),x.getCategory(),x.getCode(),x.getName(),x.isActive());}
}
